package com.mushafi.qa;
import android.app.*;import android.util.Base64;import java.io.*;import android.content.*;import android.graphics.*;import android.os.*;import android.webkit.*;import android.view.*;import com.mushafi.app.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Single-window video overlay and compositor regression; never taps the returned screen. */
final class BroadcastReturnChecks {
 static void need(boolean value,String message)throws Exception{if(!value)throw new Exception(message);}
 static Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 static String js(Instrumentation i,WebView web,String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> result=new AtomicReference<>();i.runOnMainSync(()->web.evaluateJavascript(code,v->{result.set(v);latch.countDown();}));need(latch.await(12,TimeUnit.SECONDS),"JavaScript callback: "+code);return result.get();}
 static boolean colored(Instrumentation i){Bitmap screen=i.getUiAutomation().takeScreenshot();if(screen==null)return false;int matches=0;for(int y=80;y<screen.getHeight()-80;y+=8)for(int x=15;x<screen.getWidth()-15;x+=8){int p=screen.getPixel(x,y);if(Math.abs(Color.red(p)-190)<8&&Math.abs(Color.green(p)-45)<8&&Math.abs(Color.blue(p)-65)<8)matches++;}screen.recycle();return matches>80;}
 static void run(Instrumentation i)throws Exception{
  String fixture="<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;background:#173f33;color:white;font:24px sans-serif}section{height:55vh;margin:30px;background:rgb(190,45,65);padding:25px}</style><section>Broadcast list return fixture</section><p id='anchor'>Retained DOM and scroll</p><script>window.returnFixtureReady=true;window.fixtureToken='preserve-me';requestAnimationFrame(function(){AndroidReader.startupReady();});</script>";
  Application app=(Application)i.getTargetContext().getApplicationContext();Application.ActivityLifecycleCallbacks loader=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){}public void onActivityStarted(Activity a){if(a instanceof MainActivity)try{WebView w=(WebView)field(a,"web");w.stopLoading();w.loadDataWithBaseURL("https://appassets.androidplatform.net/assets/index.html",fixture,"text/html","UTF-8",null);}catch(Exception e){throw new RuntimeException(e);}}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
  i.runOnMainSync(()->app.registerActivityLifecycleCallbacks(loader));MainActivity main=(MainActivity)i.startActivitySync(new Intent(i.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));i.runOnMainSync(()->app.unregisterActivityLifecycleCallbacks(loader));i.waitForIdleSync();WebView web=(WebView)field(main,"web");
  long ready=System.currentTimeMillis()+15000;while(!"true".equals(js(i,web,"window.returnFixtureReady===true"))&&System.currentTimeMillis()<ready)Thread.sleep(150);long painted=System.currentTimeMillis()+10000;while(!colored(i)&&System.currentTimeMillis()<painted)Thread.sleep(120);need(colored(i),"caller fixture visibly painted before opening broadcast");
  Method official=LiveBroadcastView.class.getDeclaredMethod("officialBroadcastEmbed",android.net.Uri.class);official.setAccessible(true);need((Boolean)official.invoke(null,android.net.Uri.parse("https://aloula.sba.sa/ar/live/quran?embed=true")),"Quran embed allowed");need((Boolean)official.invoke(null,android.net.Uri.parse("https://aloula.sba.sa/ar/live/sunna?embed=true")),"Sunna embed allowed");need(!(Boolean)official.invoke(null,android.net.Uri.parse("https://aloula.sba.sa.evil.test/ar/live/sunna?embed=true")),"untrusted host rejected");
  WebView reused=null;Object window=main.getWindow().getDecorView().getWindowToken();
  for(String city:new String[]{"makkah","madinah"}){
   i.runOnMainSync(()->main.openLiveBroadcast(city,false));i.waitForIdleSync();LiveBroadcastView live=(LiveBroadcastView)field(main,"broadcastView");need(live!=null&&live.isOpen(),"broadcast overlay opened");need((Boolean)field(main,"foreground")&&main.hasWindowFocus(),"caller Activity stays resumed and focused during video");need(main.getWindow().getDecorView().getWindowToken()==window,"no window transition");WebView video=(WebView)field(live,"player");if(reused!=null)need(reused==video,"same isolated player reused across both channels");reused=video;
   AtomicBoolean isolated=new AtomicBoolean();i.runOnMainSync(()->isolated.set(!video.getSettings().getAllowFileAccess()&&!video.getSettings().getAllowContentAccess()&&video.getSettings().getMediaPlaybackRequiresUserGesture()));need(isolated.get(),"internet player remains isolated");
   ByteArrayOutputStream clip=new ByteArrayOutputStream();try(InputStream in=i.getContext().getAssets().open("back-return.mp4")){byte[] bytes=new byte[4096];int count;while((count=in.read(bytes))!=-1)clip.write(bytes,0,count);}
   String data=Base64.encodeToString(clip.toByteArray(),Base64.NO_WRAP);String media="<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;background:black}video{width:100vw;height:80vh}</style><video muted autoplay loop playsinline onclick='window.tapCount=(window.tapCount||0)+1;this.play().catch(function(e){window.playError=String(e);})' src='data:video/mp4;base64,"+data+"'></video><script>window.pauseLiveBroadcast=function(){document.querySelector('video').pause();};</script>";
   i.runOnMainSync(()->{video.stopLoading();video.setWebViewClient(new WebViewClient());video.getSettings().setMediaPlaybackRequiresUserGesture(false);video.loadDataWithBaseURL("https://mushafi-support.mohammedasif241.chatgpt.site/live/"+city,media,"text/html","UTF-8",null);});Thread.sleep(700);
   need("\"undefined\"".equals(js(i,video,"typeof window.AndroidReader")),"no AndroidReader bridge on player");long decoding=System.currentTimeMillis()+12000;while(!"true".equals(js(i,video,"!!document.querySelector('video')&&document.querySelector('video').currentTime>0"))&&System.currentTimeMillis()<decoding)Thread.sleep(150);need("true".equals(js(i,video,"document.querySelector('video').currentTime>0")),"video actually playing before returning: "+city+" "+js(i,video,"JSON.stringify({clicks:window.tapCount,hidden:document.hidden,paused:document.querySelector('video').paused,ready:document.querySelector('video').readyState,error:window.playError})"));
   i.runOnMainSync(()->video.getSettings().setMediaPlaybackRequiresUserGesture(true));
   Thread.sleep(1500);if(city.equals("madinah")){AtomicBoolean hidden=new AtomicBoolean();i.runOnMainSync(()->{video.getWebChromeClient().onShowCustomView(new android.widget.FrameLayout(main),()->hidden.set(true));main.onBackPressed();});need(hidden.get()&&live.isOpen(),"first back restores player from fullscreen");}
   i.runOnMainSync(main::onBackPressed);long end=System.currentTimeMillis()+10000;while((!main.hasWindowFocus()||!colored(i))&&System.currentTimeMillis()<end)Thread.sleep(120);need(main.hasWindowFocus(),"caller regains window focus");need(colored(i),"caller visible without touching screen");need(!main.isFinishing(),"back does not close application");need("\"preserve-me\"".equals(js(i,web,"window.fixtureToken")),"original DOM retained, no reload/navigation reset");need(!live.isOpen()&&((View)field(live,"root")).getVisibility()==View.GONE,"overlay closed in same window");need(video.isAttachedToWindow(),"player is retained instead of destroyed on return");need("true".equals(js(i,video,"document.querySelector('video').paused")),"retained player stops media when closed");
   Thread.sleep(700);need(colored(i),"caller remains painted after video WebView cleanup");
  }
  i.runOnMainSync(main::finish);
 }
}
